import React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import SEO from "../components/seo";

const CaseStudiesPage: React.FC = () => {
  const { t } = useTranslation("caseStudies");

  const cases = (t("cases", { returnObjects: true }) as Array<{
    badge: string; title: string;
    before: string[]; after: Array<{ num: string; unit: string }>;
    quote: string; tags: string[];
  }>);

  return (
    <Layout activeNav="case-studies">
      <div className="cc-page-wrap">
        <div className="cc-container cc-page-header">
          <div className="section-label">
            <span className="num">00</span>
            <span className="rule" />
            <span className="name">{t("sectionName")}</span>
          </div>
          <h1 className="text-h1 max-w-[640px]">{t("title")}</h1>
          <p className="text-lg-body max-w-[560px] mt-4">{t("sub")}</p>
        </div>

        <div className="section-divider cc-container" />

        <div className="cc-container">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {cases.map((cs) => (
              <div key={cs.title} className="cc-card">
                <span className="cc-badge cc-badge-blue">{cs.badge}</span>
                <h2 className="text-h2 mt-4 break-words">{cs.title}</h2>

                <div className="grid grid-cols-2 gap-6 mt-6 min-w-0">
                  <div className="min-w-0">
                    <p className="cc-cs-label">{t("beforeLabel")}</p>
                    <ul className="flex flex-col gap-2">
                      {cs.before.map((b) => (
                        <li key={b} className="cc-before-item">
                          <span className="cc-before-bullet">×</span>{b}
                        </li>
                      ))}
                    </ul>
                  </div>
                  <div className="min-w-0">
                    <p className="cc-cs-label">{t("afterLabel")}</p>
                    <div className="flex flex-col gap-2">
                      {cs.after.map((a) => (
                        <div key={a.unit} className="flex flex-wrap items-baseline gap-x-1.5 gap-y-0.5">
                          <span className="cc-stat-num break-words">{a.num}</span>
                          <span className="cc-stat-unit break-words">{a.unit}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>

                <blockquote className="cc-blockquote">{cs.quote}</blockquote>

                <div className="flex flex-wrap gap-2 mt-5 pt-4 border-t border-[var(--border-1)]">
                  {cs.tags.map((tag) => <span key={tag} className="cc-tag">{tag}</span>)}
                </div>
              </div>
            ))}
          </div>

          {/* CTA */}
          <div className="cc-cta-box">
            <h2 className="text-h2">{t("ctaTitle")}</h2>
            <p className="text-lg-body max-w-[520px] mx-auto mt-4">{t("ctaSub")}</p>
            <Link to="/contact/" className="btn-primary inline-flex mt-8">
              {t("ctaBtn")}
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
            </Link>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default CaseStudiesPage;

export const Head: HeadFC = ({ data, location }: any) => (
  <SEO
    data={data.allDataJson.nodes[0]}
    title="Case Studies - Code Crafted"
    description="Real results from custom business applications built for trades, healthcare, and professional services businesses in Canada."
    language={data.locales?.edges?.[0]?.node?.language}
    originalPath={location.pathname}
    pageSchemaType="CollectionPage"
    schemaType="ProfessionalService"
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges { node { ns data language } }
    }
    allDataJson {
      nodes {
        companyName address city province country postalCode
        phone email instagram facebook linkedin whatsapp url
        founder { name jobTitle sameAs }
      }
    }
  }
`;
